pred_cypher:
MATCH (c:Case)-[:FALLS_UNDER]->(ag:AgeGroup)
WHERE EXISTS {
  MATCH (c)-[:IS_PRIMARY_SUSPECT]->(d:Drug)
  WHERE d.primarySubstabce = "KETOTIFEN" OR d.primarySubstabce = "FERROUS FUMARATE" OR d.primarySubstabce = "BISOPROLOL FUMARATE"
}
RETURN ag.ageGroup, avg(c.age) AS average_age, count(c) AS case_count
